from pathlib import Path
p=Path('site/index.html')
s=p.read_text(encoding='utf-8')
head='''<link rel="manifest" href="./manifest.webmanifest"><meta name="theme-color" content="#1769e0"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="default"><link rel="apple-touch-icon" href="./icons/icon-192.png">'''
s=s.replace('</head>',head+'</head>')
# Prefer the local Tiny model generated by the workflow.
s=s.replace('https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-tiny.bin','./models/ggml-tiny.bin')
s=s.replace('https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-tiny.en.bin','./models/ggml-tiny.bin')
script='''<script>if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js'));}</script>'''
s=s.replace('</body>',script+'</body>')
p.write_text(s,encoding='utf-8')
